// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: sender, calleeSuffix toggles which callee impl to deploy, and v amount
    function testFuzz_property(address from, bool useGood, uint256 v) public {
        // keep _tos length exactly 1 to simplify observation but still general
        address[] memory tos = new address[](1);

        // Deploy either a good callee (implements transferFrom with correct selector) or a bad callee
        // The fuzzer chooses which by useGood. We still fuzz 'from' and 'v'.
        GoodCallee good = new GoodCallee();
        BadCallee bad = new BadCallee();
        address callee = useGood ? address(good) : address(bad);

        tos[0] = address(0x1234); // recipient arg content doesn't matter for the property

        // The property: for any inputs, the reference implementation's transfer will return true (no revert)
        // when the callee implements transferFrom correctly. The mutant that uses a wrong selector will
        // cause the call to BadCallee to fail and thus transfer to revert for at least some inputs.

        bool ok;
        try c.transfer(from, callee, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: when we pass a callee that implements the expected transferFrom selector (useGood==true),
        // c.transfer must succeed for all inputs. The buggy mutant (which uses a wrong selector) will fail
        // when the callee expects the correct selector. The single assertion observes c via its external call outcome.
        if (useGood) {
            assertTrue(ok);
        } else {
            // when using the bad callee, the correct contract would still succeed only if the selector matched;
            // but since we are testing the reference here, we don't require anything for the bad callee path.
            // Keep this branch permissive so the single assert above is the required universal property.
            assertTrue(true);
        }
    }
}

// A callee that implements the exact function selector expected by the reference:
contract GoodCallee {
    // Matches: transferFrom(address,address,uint256)
    event Called(address from, address to, uint256 v);
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        return true;
    }
}

// A callee that does NOT implement the expected selector; any call with that selector will hit fallback and revert
contract BadCallee {
    fallback() external payable {
        revert("bad selector");
    }
}
